  /** The glyph an action draws while it is on: the glyph's `Fill` form, else the glyph. */
  fun active(icon: IconData): IconData = when {
    icon === like -> likeFill
    icon === bookmark -> bookmarkFill
    icon === play -> playFill
    icon === home -> homeFill
    icon === settings -> settingsFill
    else -> icon
  }

  /** A tab's icon by name, and its selected form. */
  fun named(name: String): Pair<IconData, IconData> = when (name) {
    "home" -> home to homeFill
    "settings" -> settings to settingsFill
    else -> home to homeFill
  }
}
